import zipfile
import os

# Extract for detailed verification
verify_dir = '/tmp/verify_final'
os.makedirs(verify_dir, exist_ok=True)

with zipfile.ZipFile('/root/safety_audit_brief_final.hwpx', 'r') as z:
    z.extractall(verify_dir)

# Check for remaining placeholders
print('=== Checking for remaining placeholders ===')
for root, dirs, files in os.walk(verify_dir):
    for f in files:
        if f.endswith('.xml') or f.endswith('.hpf'):
            path = os.path.join(root, f)
            with open(path, 'r', encoding='utf-8') as fp:
                content = fp.read()
            if '{{' in content:
                print(f'FOUND: {{placeholder}} in {f}')
            else:
                print(f'OK: No placeholders in {f}')

print()

# Check date format
print('=== Checking date format ===')
for root, dirs, files in os.walk(verify_dir):
    for f in files:
        if f.endswith('.xml') or f.endswith('.hpf'):
            path = os.path.join(root, f)
            with open(path, 'r', encoding='utf-8') as fp:
                content = fp.read()
            if '2026.06.18' in content:
                print(f'OK: Date in correct format (YYYY.MM.DD) in {f}')
            if '2026-06-18' in content:
                print(f'ERROR: Date in wrong format (YYYY-MM-DD) in {f}')

print()

# Check risk tier
print('=== Checking risk tier with severity ===')
for root, dirs, files in os.walk(verify_dir):
    for f in files:
        if f.endswith('.xml') or f.endswith('.hpf'):
            path = os.path.join(root, f)
            with open(path, 'r', encoding='utf-8') as fp:
                content = fp.read()
            if 'High 즉시조치' in content:
                print(f'OK: Risk tier with severity found in {f}')

print()

# Check linesegarray removed
print('=== Checking linesegarray removed ===')
for root, dirs, files in os.walk(verify_dir):
    for f in files:
        if f.endswith('.xml') or f.endswith('.hpf'):
